			function selectHopeSprtCdLst(psSeltVal){
			    
			    var cmbBox =   app.lookup("cbg_HOPE_SPRT_CD_LST");
			    var grdFomLot = app.lookup("grpRqstAplyInfo1").getLayout();
			    
			    /* 희망지원코드목록(다건선택)*/
			    var sHopeSprtCdLst = app.lookup("dsCAB120Save").getValue(0, "HOPE_SPRT_CD_LST");
			    var sEnableYn = '';    
			    
			//    if(psSeltVal == '' || psSeltVal == null || psSeltVal == "" || psSeltVal == undefined){
			//        console.log('null or x');
			//    }

			    app.lookup("opt_HOPE_SPRT_ETC_CN").style.removeClass("label");
			    app.lookup("opt_HOPE_SPRT_ETC_CN").style.removeClass("label require");
			    
			    /* 다건선택 중 기타가 선택된 경우*/
			    if(psSeltVal.indexOf('999') >= 0){
			        cmbBox.putValue("");
			        sEnableYn = 'value == "999"'; /* 999제외 false / 999true*/
			        
			        app.lookup("cbg_HOPE_SPRT_CD_LST").enabledItemExp = sEnableYn;
			        
			        if(msCrudType =="CREATE" || msCrudType == "UPDATE"){
			            util.Control.reset(app, "txa_HOPE_SPRT_ETC_CN");
			        }        
			        
			        cmbBox.putValue("999");
			        
			        app.lookup("opt_HOPE_SPRT_ETC_CN").style.addClass("label require");
			        app.lookup("txa_HOPE_SPRT_ETC_CN").userAttr("required", "Y");        
			        
			        grdFomLot.setRowVisible(6, true);
			        grdFomLot.setRowVisible(7, true);
			    }else if(psSeltVal.indexOf('999') == -1){
			        
			        sEnableYn = 'value != "999" || value == "999"';  /* 999제외 true /999 false*/      
			        app.lookup("cbg_HOPE_SPRT_CD_LST").enabledItemExp = sEnableYn;
			        
			        if(msCrudType =="CREATE" || msCrudType == "UPDATE"){
			            util.Control.reset(app, "txa_HOPE_SPRT_ETC_CN");
			        }        
			        
			        app.lookup("opt_HOPE_SPRT_ETC_CN").style.addClass("label");        
			        app.lookup("txa_HOPE_SPRT_ETC_CN").userAttr("required", "N");          
			        
			        grdFomLot.setRowVisible(6, false);
			        grdFomLot.setRowVisible(7, false);
			    }
			    
			    app.lookup("grpRqstAplyInfo1").redraw();
			}

